\label{Theorem:1.1}
	Assume $(K)$ and $(L)$.
	Let $u_0 \in L^1(\mathbb{R}^N)$.
	\begin{itemize}
		\item[\rm (a)]
		There exists a unique $L^1$-solution $u\in C([0,\infty);L^1(\mathbb{R}^N))$ to problem \eqref{eq:P}
		satisfying
		$$
			\|u\|_{L^\infty(0,\infty; L^1(\mathbb{R}^N))} \leq \|u_0\|_{L^1(\mathbb{R}^N)}.
		$$
		Furthermore, it holds that
		$$
			\ell*\|\Phi(u)\|_{L_{\rm loc}^1(\mathbb{R}^N)} \in C([0,\infty)) \cap L^\infty(0,\infty)\,\,\,{\rm with}\,\,\,
			\left(\ell*\|\Phi(u)\|_{L_{\rm loc}^1(\mathbb{R}^N)}\right)(0)=0.
		$$
		\item[\rm (b)]
		Let $u,v \in C([0,\infty);L^1(\mathbb{R}^N))$ be $L^1$-solutions to problem \eqref{eq:P} 
		with initial data $u_0,v_0 \in L^1(\mathbb{R}^N)$, respectively.
		Then it holds that
		\begin{equation}
		\label{eq:1.3}
			\int_{\mathbb{R}^N}[u(x,t)-v(x,t)]_+\,\dee x \le \int_{\mathbb{R}^N}[u_0(x)-v_0(x)]_+\,\dee x,\quad t\ge0.
		\end{equation}
		In particular,
		\begin{equation}
		\label{eq:1.4}
			\|u(t)-v(t)\|_{L^1(\mathbb{R}^N)} \le \|u_0-v_0\|_{L^1(\mathbb{R}^N)},\quad t \ge 0.
		\end{equation}
	\end{itemize}

