ref_dict.Theorem:3.1:
\begin{theorem}
\label{Theorem:3.1}
	Assume $(K)$ and $(L)$.
	Let $u_0$ be a bounded function.
	Then the following assertions hold.
	\begin{itemize}
	\item[\rm(i)]
		Problem \eqref{eq:IBP} possesses a global weak solution 
		$u \in C([0,\infty);H^{-1}(\Omega))$ with $u(0)=u_0$ in $H^{-1}(\Omega)$ satisfying
		\begin{equation}
		\label{eq:3.2}
		\ell*\|\nabla\Phi(u)\|_{L^2(\Omega)}^2 \in L^\infty(0,\infty),\quad
		\ell*\|\partial_t(k*[u-u_0])\|_{H^{-1}(\Omega)}^2 \in L^\infty(0,\infty).
		\end{equation}
		Furthermore, for any $q\in[1,\infty]$, the solution $u$ also belongs to 
		$L^\infty(0,\infty\,;\,L^q(\Omega))$, and satisfies
		\begin{equation}
		\label{eq:3.3}
			\|u\|_{L^\infty(0,\infty\,;\,L^q(\Omega))} \le\|u_0\|_{L^q(\Omega)}.
		\end{equation}
	\item[\rm(ii)]
		Let $u, v$ be global weak solutions to problem \eqref{eq:IBP} with bounded initial data 
		$u_0,v_0$, respectively.
		Furthermore, let $\zeta$ be a nonnegative classical solution to problem
		\begin{equation}
		\label{eq:3.4}
			-\Delta\zeta = 1\quad{\rm in}\quad\Omega,\qquad
			\zeta=0\quad{\rm on}\quad\partial\Omega.
		\end{equation}
		Then it holds that
		\begin{equation}
		\label{eq:3.5}
			\|u(t)-v(t)\|_{L^1_\zeta(\Omega)} + \left(\ell*\|\Phi(u)-\Phi(v)\|_{L^1(\Omega)}\right)(t)
			\le \|u_0-v_0\|_{L^1_\zeta(\Omega)},\quad t\ge0,
		\end{equation}
		where $\|f\|_{L^1_\zeta(\Omega)}:=\|f\zeta\|_{L^1(\Omega)}$.
		In particular,
		\begin{equation}
		\label{eq:3.6}
			\int_{\Omega}[u(x,t)-v(x,t)]_+\zeta(x)\,\dee x 
			\le \int_{\Omega}[u_0(x)-v_0(x)]_+\zeta(x)\,\dee x,
			\quad t\ge0.
		\end{equation}
	\end{itemize}
\end{theorem}

ref_dict.Definition:3.1:
\begin{definition}
\label{Definition:3.1}
	Let $T>0$.
	We say that $u \in L^2(0,T;L^2(\Omega))$ is a weak solution to problem \eqref{eq:IBP} in $\Omega\times[0,T)$ if
	\begin{itemize}
		\item[\rm (i)] $k*[u-u_0] \in H^1(0,T; H^{-1}(\Omega))$ with $\left(k*[u-u_0]\right)(0)=0$,
		\item[\rm (ii)] $\Phi(u) \in L^2(0,T; H^1(\Omega))$,
		\item[\rm (iii)] $u$ satisfies the identity
		\begin{equation}
		\label{eq:3.1}
			\begin{aligned}
			&
			\int_0^T\int_{\Omega}(k*[u(x,\cdot)-u_0(x)])(t)\partial_t\psi(x,t)\,\dee x\,\dee t 
			\\
			&\hspace{5cm}
			-\int_0^T\int_{\Omega}\nabla\Phi(u(x,t))\cdot\nabla\psi(x,t)\,\dee x\,\dee t = 0
			\end{aligned}
		\end{equation}
		for any $\psi \in H^1(0,T; H_0^1(\Omega))$ with $\psi\bigl|_{t=T}=0$.
	\end{itemize}
	Moreover, 
	we say that $u \in L_{\rm loc}^2(0,\infty;L^2(\Omega))$ is a global weak solution to problem \eqref{eq:IBP}
	in $\Omega\times[0,\infty)$ if above conditions {\rm (i)}--{\rm (iii)} hold for any fixed $T>0$.
\end{definition}

ref_dict.Theorem:1.3:
\begin{theorem}
\label{Theorem:1.3}
	Let $p\in[1,\infty]$, and let
	$u \in C([0,\infty); L^1(\R^N)) \cap L^\infty(0,\infty;L^p(\R^N))$ be a nonnegative $L^1$-solution 
	of \eqref{eq:TFDE} with nonnegative initial data $u_0 \in L^1(\R^N) \cap L^p(\R^N)$.
	Then it holds that
	\begin{equation}
	\label{eq:1.6}
		\|u(t)\|_{L^p(\R^N)}\ge C\left(1+t^{\frac{\alpha}{m}}\right)^{-1},\quad t>0,
	\end{equation}
	where $C$ depends only on $m$, $N$, $\alpha$, $p$, and $\|u_0\|_{L^p(\R^N)}$.
\end{theorem}

ref_dict.Definition:3.2:
\begin{definition}
\label{Definition:3.2}
	Let $u_0\in L^1(\Omega)$.
	We say that $u\in L^\infty(0,\infty; L^1(\Omega))$ is an $L^1$-solution to problem \eqref{eq:IBP} if
	\begin{itemize}
		\item[\rm (i)] 
		$\Phi(u) \in L_{\rm loc}^1(0,\infty; L^1(\Omega))$ 
		with $\ell*\|\Phi(u)\|_{L^1(\Omega)} \in L^\infty(0,\infty)$,
		\item[\rm (ii)] 
		$u$ satisfies the identity
		\begin{equation}
		\label{eq:3.22}
			\int_\Omega(u(x,t)-u_0(x))\phi(x)\,\dee x 
			= \left(\ell*\left[\int_{\Omega}\Phi(u(x,\cdot))\Delta\phi(x)\,\dee x\right]\right)(t),
			\quad{\rm a.e.}\,\,\,t > 0,
		\end{equation}
		for any $\phi\in C_0^{\infty}(\Omega)$.
	\end{itemize}
\end{definition}

