		Let $(v_-, u_-, \theta_-) \in R_1 (v_+, u_+, \theta_+)$ and $\delta=|v_+-v_-|+|u_+-u_-|+|\theta_+-\theta_-|$. Assume the initial data $(v_0, u_0, \theta_0, q_0, S_0)$ satisfy
		\begin{align*}
			(v_0- v_0^r, u_0-u_0^r, \theta_0-\theta^r, q_0,  S_0) \in L^2,\\
			( (v_0)_x, (u_0)_x, (\theta_0)_x)\in H^1, (q_0, S_0) \in H^2,
		\end{align*}
		and there exists a positive constant $\epsilon_0$ such that if $I_0+\delta < \epsilon_0$, then the initial value problem \eqref{1.3}-\eqref{1.4} has a unique global solution in time satisfying
		\begin{align}\label{1.9}
			\begin{cases}
				(v-v_0^r, u-u_0^r, \theta-\theta_0^r, q,  S)\in C^0(0, +\infty, L^2),\\
				(v_x, u_x, \theta_x)\in C^0(0, +\infty, H^1)\cap L^2(0, +\infty, H^1), (q, S) \in C^0(0, +\infty, H^2)\cap L^2 (0, +\infty, H^2).
