ref_dict.thm3.1:
\begin{theorem}\label{thm3.1}
		Let $(v_-,u_-,\theta_-)\in R_1(v_+,u_+,\theta_+)$ and $\delta=|v_+-v_-|+|u_+-u_-|+|\theta_+-\theta_-|$. Assume the initial data $(\varphi_0,\psi_0,\tilde{\theta}_0,\tilde{q}_0,\tilde{S}_0)\in H^2$ and let $E_0:=\|(\varphi_0,\psi_0,\tilde{\theta}_0,\tilde{q}_0,\tilde{S}_0)\|_{H^2}^2$. Then, there exists a positive constant $\delta_1$ such that if $E_0+\delta<\delta_1$, the initial value problem \eqref{3.10}-\eqref{y3.11} has a unique global solution in time satisfying
		\begin{align}\label{3-4}
			&(\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})(t,x)\in C^0(0,+\infty,H^2),\\
			\label{3-5}&(\varphi_x,\psi_x)(t,x)\in L^2(0,+\infty,H^1),\quad(\tilde{\theta}_x,\tilde{q}_x,\tilde{S}_x)\in L^2(0,+\infty,H^2).
		\end{align}
		Moreover, this solution decay to $(0,0,0)$ uniformly in $x$ as $t\rightarrow \infty$:
		\begin{align*}
			\|(\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})\|_{W^{1,\infty}}\rightarrow 0,\quad as \quad t\rightarrow \infty.
		\end{align*}
	\end{theorem}

ref_dict.prop3.2:
\begin{proposition}\label{prop3.2}
		Let $T>0$ and suppose $(\phi,\psi,\tilde\theta,\tilde q,\tilde S)$ is a smooth solution
		on $[0,T]$ with
		\[
		(\phi,\psi,\tilde\theta,\tilde q,\tilde S)\in C^0([0,T];H^2)\cap C^1([0,T];H^1).
		\]
		Then there exist constants
		$C>0$ and $\delta_2>0$ (independent of $T$) such that if
		\begin{align}\label{3-6}
			E(T)+\delta<\delta_2,
		\end{align}
		then the solution $(\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})$ satisfies
		\begin{align}\label{3-7}
			E(t) +\int_{0}^{s} \mathcal{D}(t) \mathrm{d}s \le C\big( E_0 + E(t)^{3/2} + \delta^\theta \big)
		\end{align}
		for all $t\in(0,T)$ with $\theta=\min\{\frac{1}{2},\frac{3}{2}-\frac{1}{q}\}$.
	\end{proposition}

