\begin{thm}\label{mainly-case-2}
Under the same assumptions of Theorem A, but with the condition that now $\alpha_M\le 0$, in any one of the following situations:
\begin{enumerate}
    \item $\alpha_M=0$,\, $L(\mathbf{p})\neq 0$,\, $\det \big(D^2f^*(p_{\tau+1},\cdots,p_m)\big)\neq 0$
    \item $\alpha_M=0$, $L(\mathbf{p})=0$,  $D(\mathbf{p})\neq 0$, $\det \big(D^2f^*(p_{\tau+1},\cdots,p_m)\big)\neq 0$
    \item $\alpha_M<0$, $D(\mathbf{p})\neq 0$.
\end{enumerate} the same uniqueness property as in Theorem A holds.
\end{thm}

