    \end{align}
    Combining it with the inequality 
    \begin{align*}
        \left( 1- \frac{1}{m} \right)^{\ell}\leq1-\frac{\ell}{m}+\binom{\ell}{2}\left(\frac{1}{m}\right)^2, 
    \end{align*}
    we obtain $m <  \frac{\ell(\ell-1)}{2(\ell-r)}$. 

    It remains to prove that $m < r/\alpha$. 
    Define $\theta \coloneqq r/m$. 
    Then it follows from~\eqref{eq:m-upper-bound} and the inequality $\ln(1+x) \le x$ for $x > -1$ that 
    \begin{align*}
        1-\theta 
        = \frac{m-r}{m}
        < \left( 1- \frac{1}{m} \right)^{\ell} 
        = \exp\left(\ell \ln\left(1-\frac{1}{m}\right) \right) 
        \le \exp\left(-\frac{\ell}{m}\right) 
        = \mathrm{e}^{-t\theta}.
    \end{align*}
    In other words, we have $h_t(\theta)< 0$.
    Since $h_t$ is unimodal on $(0,\infty)$ and $h_{t}(0) = 0$, we have $\theta > \alpha$, which implies that $m < r/\alpha$.
    This proves~\ref{Lemma:m-upper-bound}, and thus completing the proof of Lemma~\ref{Lemma:m-bounds}.
