theorem.content:
\label{thm_existence}
The functional $\mathcal F_c$ admits a unique minimizer $\rho_c \in X$. Moreover, the following complete characterization of the minimizer $\rho_c$ holds true.
\begin{itemize}
\item[a)] If $c<r^2$, in the equation 
\begin{equation*}
\cosh\frac{2h}{E}=\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}},
\end{equation*}
there exists only one solution $\smileacc{E}(c)>\Pi_0(h,r)$ and 
\[
\rho_c(x)=\sqrt{
    \frac{\smileacc{E}}{2}\sqrt{\smileacc{E}^2-4c}\cosh\frac{2x}{\smileacc{E}}+\frac{\smileacc{E}^2}{2}-c}.
\]
In this case, $\rho_c\in C^\infty([-h,h])$, it is even, strictly convex and $\rho_0<\rho_c<r$ on $(-h,h)$.
\item[b)] If $c=r^2$, then $\rho_c(x)=r$ for all $x \in [-h,h]$.
\item[c)] If $c>r^2$, the equation 
\begin{equation*}
\cosh\frac{2h}{E}=\frac{-2r^2+E^2-4c}{E\sqrt{E^2-4c}}
\end{equation*}
has a unique solution $\frownacc{E}(c)$ which is positive and 
\[
\rho_c(x)=\sqrt{
    -\frac{\frownacc{E}}{2}\sqrt{\frownacc{E}^2-4c}\cosh\frac{2x}{\frownacc{E}}+\frac{\frownacc{E}^2}{2}-c}.
\]
In this case, $\rho_c\in C^\infty([-h,h])$, it is even, strictly concave and $r<\rho_c<\rho_\infty$ on $(-h,h)$ where 
$$\rho_\infty(x)=\sqrt{h^2+r^2-x^2}.$$
Moreover, $\rho_c\to \rho_\infty$ uniformly on $[-h,h]$ as $c\to +\infty$. 
\end{itemize}
Finally, $\rho_{c_1}<\rho_{c_2}$ on $(-h,h)$ whenever $c_1<c_2$.

ref_dict.thm:minimo_rilassato:
\begin{theorem}[\protect{\cite[Theorem 5.1]{bm1991}}]\label{thm:minimo_rilassato}
    \noindent Assume that $g\in C^2([a_0, + \infty))$, for some $a_0>0$, satisfies one of the following conditions: 
    \begin{itemize}
    \item[i)] $g>0$ is monotone;
    \item[ii)] if there exists $\overline{x} \in [a_0,+\infty)$ such that $g'(\overline{x}) = 0$ then $g''(\overline{x})>0$.
    \end{itemize}
    Then the problem
    $$
    \min\left\{\overline{\mathcal{G}}(\rho): \rho\in W_{\rm loc}^{1,1}(a,b),\,\rho\geq a_0\right\}
    $$
    admits a solution.
\end{theorem}

ref_dict.prop:proprieta_bvp:
\begin{proposition}
\label{prop:proprieta_bvp}
Let $\rho \in C^2([-h,h])$ be a strictly positive solution of the boundary value problem 
\begin{equation}\label{bvp}
\left\{\begin{array}{ll}
\displaystyle \rho''=\frac{(\rho^2-c)(1+(\rho')^2)}{\rho(\rho^2+c)}\\
\\
\rho(-h)=\rho(h)=r.
\end{array}\right.
\end{equation}
Then the following facts hold true.
\begin{itemize}
\item[a)] If $c<r^2$, then 
\begin{equation}\label{rho-}
\rho(x)=\sqrt{ \frac{E}{2}\sqrt{E^2-4c}\cosh\frac{2x}{E}+\frac{E^2}{2}-c}
\end{equation}
where $E= E(c)$ is a positive constant that satisfies 
\begin{equation}\label{p-}
\cosh\frac{2h}{E}=\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}}.
\end{equation}
Moreover, $\rho$ is even, strictly convex and $\rho_0<\rho<r$ on $(-h,h)$.
\item[b)] If $c>r^2$, then 
\begin{equation}\label{rho+}
\rho(x)=\sqrt{-\frac{E}{2}\sqrt{E^2-4c}\cosh\frac{2x}{E}+\frac{E^2}{2}-c}
\end{equation}
where $E= E(c)$ is a positive constant that satisfies 
\begin{equation}\label{p+}
\cosh\frac{2h}{E}=-\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}}.
\end{equation} 
Moreover, $\rho$ is even, strictly concave and $r<\rho$ on $(-h,h)$.
\end{itemize}
Moreover, both in cases a) and c), it holds 
\begin{equation}\label{Ec}
E^2-4c>0.
\end{equation}
\end{proposition}

